#!/bin/bash
# Manual Docker Test - Keeps container running for browser testing

set -e

echo "🧪 Manual Docker Test - AI Interviewer"
echo "======================================"

# Colors
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
RED='\033[0;31m'
NC='\033[0m'

# Load .env files
echo -e "\n${BLUE}📋 Loading environment variables from .env files...${NC}"

ENV_VARS=""

if [ -f "server/.env" ]; then
    echo -e "${GREEN}✅ Loading server/.env${NC}"
    while IFS= read -r line || [ -n "$line" ]; do
        # Skip comments and empty lines
        [[ "$line" =~ ^#.*$ ]] && continue
        [[ -z "$line" ]] && continue
        
        # Extract key=value
        if [[ "$line" =~ ^([^=]+)=(.*)$ ]]; then
            key="${BASH_REMATCH[1]}"
            value="${BASH_REMATCH[2]}"
            # Remove quotes if present
            value=$(echo "$value" | sed "s/^['\"]//; s/['\"]$//")
            # Remove inline comments
            value=$(echo "$value" | sed 's/#.*$//' | xargs)
            
            if [ -n "$value" ] && [ "$value" != "..." ]; then
                ENV_VARS="$ENV_VARS -e $key=\"$value\""
            fi
        fi
    done < server/.env
fi

if [ -f "web_server/.env" ]; then
    echo -e "${GREEN}✅ Loading web_server/.env${NC}"
    while IFS= read -r line || [ -n "$line" ]; do
        # Skip comments and empty lines
        [[ "$line" =~ ^#.*$ ]] && continue
        [[ -z "$line" ]] && continue
        
        # Extract key=value
        if [[ "$line" =~ ^([^=]+)=(.*)$ ]]; then
            key="${BASH_REMATCH[1]}"
            value="${BASH_REMATCH[2]}"
            # Remove quotes if present
            value=$(echo "$value" | sed "s/^['\"]//; s/['\"]$//")
            # Remove inline comments
            value=$(echo "$value" | sed 's/#.*$//' | xargs)
            
            if [ -n "$value" ] && [ "$value" != "..." ]; then
                # Only add if not already in ENV_VARS
                if ! echo "$ENV_VARS" | grep -q "$key="; then
                    ENV_VARS="$ENV_VARS -e $key=\"$value\""
                fi
            fi
        fi
    done < web_server/.env
fi

# Stop any existing container
echo -e "\n${BLUE}🛑 Stopping any existing test container...${NC}"
docker stop test-web 2>/dev/null || true
docker rm test-web 2>/dev/null || true

# Start container
echo -e "\n${BLUE}🚀 Starting web server container...${NC}"
echo -e "${YELLOW}Using environment variables from .env files${NC}"

eval "docker run -d \
    --name test-web \
    -p 8009:8009 \
    --network host \
    $ENV_VARS \
    ai-interviewer-web:test"

sleep 5

# Check if running
if docker ps | grep -q test-web; then
    echo -e "${GREEN}✅ Container started!${NC}"
    
    # Wait for server to be ready
    echo -e "${BLUE}⏳ Waiting for server to be ready...${NC}"
    sleep 5
    
    # Test health
    echo -e "\n${BLUE}Testing health endpoint...${NC}"
    HEALTH=$(curl -s http://localhost:8009/health 2>/dev/null || echo "")
    if echo "$HEALTH" | grep -q "healthy"; then
        echo -e "${GREEN}✅ Health check passed!${NC}"
        echo "$HEALTH" | python -m json.tool 2>/dev/null || echo "$HEALTH"
    else
        echo -e "${YELLOW}⚠️ Health check: $HEALTH${NC}"
    fi
    
    echo -e "\n${GREEN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━.env files are NOT automatically loaded into Docker containers.${NC}"
    echo -e "${YELLOW}   Docker containers are isolated - you need to pass env vars explicitly.${NC}"
    echo ""
    echo -e "${GREEN}🌐 Web Server URLs:${NC}"
    echo -e "   📊 Dashboard: ${BLUE}http://localhost:8009/dashboard${NC}"
    echo -e "   📚 API Docs:   ${BLUE}http://localhost:8009/docs${NC}"
    echo -e "   ❤️ Health:     ${BLUE}http://localhost:8009/health${NC}"
